mapper.sql:
WHERE w.type IN ('MATERIAL', 'FACTORY')
AND w.type = #{q.warehouseType}
AND s.warehouse_id = #{q.warehouseId}

    AND (k.code ILIKE '%' || #{q.keyword} || '%' OR m.code ILIKE '%' || #{q.keyword} || '%'
         OR m.name ILIKE '%' || #{q.keyword} || '%' OR w.name ILIKE '%' || #{q.keyword} || '%'
         OR upper(k.code) IN #{code} OR upper(m.code) IN #{code})
